SELECT * FROM af_compensation_task_log
WHERE  DELETED = 0 AND TASK_TYPE = #{taskType}
AND STATUS IN

    #{status}


    AND ID > #{lastId}

AND NEXT_EXECUTION_TIME <= NOW() ORDER BY ID LIMIT 100

select *
from af_compensation_task_log
where batch_no = #{batchNo}
  and co_id = #{coId}
  and uid = #{uid}
  and task_type = #{taskType}
  and deleted = 0

select ID
from af_compensation_task_log
where batch_no = #{batchNo}
  and co_id = #{coId}
  and uid = #{uid}
  and task_type = #{taskType}
  and deleted = 0 limit 1

select ID
from af_compensation_task_log
where co_id = #{coId}
and uid = #{uid}
and task_type = #{taskType}
and STATUS = #{taskStatus}
and deleted = 0 limit 1
